import copy


def assert_not_mutated(func, *args):
    before = copy.deepcopy(args)
    result = func(*args)
    for i, (old, new) in enumerate(zip(before, args)):
        if old != new:
            raise AssertionError(f"аргумент {i} изменён")
    return result

